Évalue chaque paire question/SQL pour ce schéma SQLite.

Question à te poser : un expert SQL qui lit seulement la question française et le schéma écrirait-il une requête dont le résultat est identique à celui du SQL fourni ?

- pass : oui. La question peut être formulée naturellement, sans nommer les colonnes techniques ni décrire la syntaxe ; les choix conventionnels d'un expert (par exemple afficher le nom pour « quel client ») sont acceptables.
- fail : la question ajoute, retire ou modifie une contrainte ; le SQL renvoie des colonnes que la question ne demande pas, ou oublie une colonne demandée ; l'agrégat, le tri, la limite, la négation, la jointure ou une valeur ne correspond pas ; la question est absurde, tautologique ou mal écrite en français.
- uncertain : la question admet plusieurs lectures raisonnables qui donnent des résultats différents.

Conventions du jeu Spider, à accepter sans les pénaliser : jointure interne même pour « chaque » ou « tous » ; regroupement ou INTERSECT/EXCEPT sur un nom affiché plutôt que sur un identifiant ; doublons possibles sans DISTINCT quand la question ne demande pas explicitement des valeurs distinctes ; cas limites théoriques (homonymes, valeurs NULL, ex æquo) que la question n'évoque pas. Ne rejette que les écarts de sens réels.

Retourne exactement un verdict pour chaque identifiant fourni ; dans issues, décris brièvement le problème (liste vide si pass).

{"schema": "CREATE INDEX idx_event_organizer ON conference_event (organizer_id);

CREATE INDEX idx_registration_attendee ON event_registration (attendee_id);

CREATE INDEX idx_registration_event ON event_registration (event_id);

CREATE INDEX idx_session_event ON event_session (event_id);

CREATE INDEX idx_session_room ON event_session (room_id);

CREATE TABLE attendee (attendee_id INTEGER PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, email TEXT NOT NULL, company_name TEXT NOT NULL, job_title TEXT NOT NULL, country TEXT NOT NULL);

CREATE TABLE conference_event (event_id INTEGER PRIMARY KEY, organizer_id INTEGER NOT NULL, event_title TEXT NOT NULL, event_category TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, expected_attendance INTEGER NOT NULL, status TEXT NOT NULL, FOREIGN KEY (organizer_id) REFERENCES organizer (organizer_id));

CREATE TABLE event_registration (registration_id INTEGER PRIMARY KEY, event_id INTEGER NOT NULL, attendee_id INTEGER NOT NULL, registered_at TEXT NOT NULL, ticket_type TEXT NOT NULL, payment_status TEXT NOT NULL, check_in_status TEXT NOT NULL, FOREIGN KEY (event_id) REFERENCES conference_event (event_id), FOREIGN KEY (attendee_id) REFERENCES attendee (attendee_id));

CREATE TABLE event_session (session_id INTEGER PRIMARY KEY, event_id INTEGER NOT NULL, room_id INTEGER NOT NULL, session_title TEXT NOT NULL, session_format TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, speaker_name TEXT NOT NULL, FOREIGN KEY (event_id) REFERENCES conference_event (event_id), FOREIGN KEY (room_id) REFERENCES venue_room (room_id));

CREATE TABLE organizer (organizer_id INTEGER PRIMARY KEY, organization_name TEXT NOT NULL, contact_name TEXT NOT NULL, contact_email TEXT NOT NULL, sector TEXT NOT NULL, city TEXT NOT NULL);

CREATE TABLE venue_room (room_id INTEGER PRIMARY KEY, room_name TEXT NOT NULL, floor_number INTEGER NOT NULL, capacity INTEGER NOT NULL, room_type TEXT NOT NULL, accessibility_level TEXT NOT NULL);", "examples": [{"id": "v2:new:synthetic_046:1:0", "question": "Quels sont les différents secteurs des organisateurs ?", "sql": "SELECT DISTINCT sector FROM organizer"}, {"id": "v2:new:synthetic_046:1:1", "question": "Combien d'organisateurs différents ont-ils organisé des événements ?", "sql": "SELECT count(DISTINCT organizer_id) FROM conference_event"}, {"id": "v2:new:synthetic_046:1:2", "question": "Quels sont les identifiants des événements comportant à la fois la session d'ouverture et l'atelier sur la sécurité des données ?", "sql": "SELECT DISTINCT T3.event_id FROM event_session AS T3 JOIN conference_event AS T2 ON T3.event_id = T2.event_id JOIN event_session AS T4 ON T4.event_id = T3.event_id JOIN conference_event AS T1 ON T4.event_id = T1.event_id WHERE T3.session_title = 'Ouverture et strategie numerique' AND T4.session_title = 'Atelier securite des donnees' AND T2.event_title = 'Sommet de la transformation numerique' AND T1.status = 'termine'"}, {"id": "v2:new:synthetic_046:1:3", "question": "Quels sont les noms et les niveaux d'accessibilité des salles de type auditorium ? Triez-les par leur capacité.", "sql": "SELECT room_name, accessibility_level FROM venue_room WHERE room_type = 'auditorium' ORDER BY capacity"}, {"id": "v2:new:synthetic_046:1:4", "question": "Listez les adresses électroniques de tous les participants.", "sql": "SELECT email FROM attendee"}, {"id": "v2:new:synthetic_046:1:5", "question": "Listez les noms des organisations par ordre alphabétique.", "sql": "SELECT organization_name FROM organizer ORDER BY organization_name"}, {"id": "v2:new:synthetic_046:1:6", "question": "Quels sont les noms des salles dont la capacité est comprise entre 300 et 900 places ?", "sql": "SELECT room_name FROM venue_room WHERE capacity BETWEEN 300 AND 900"}, {"id": "v2:new:synthetic_046:1:7", "question": "Quels sont les thèmes et les statuts des événements ?", "sql": "SELECT event_category, status FROM conference_event"}, {"id": "v2:new:synthetic_046:1:8", "question": "Quelle organisation a organisé le plus d'événements ? Donnez son nom.", "sql": "SELECT T1.organization_name FROM organizer AS T1 JOIN conference_event AS T2 ON T1.organizer_id = T2.organizer_id GROUP BY T1.organization_name ORDER BY count(*) DESC LIMIT 1"}, {"id": "v2:new:synthetic_046:1:9", "question": "Pour chaque ville d'organisation, combien d'événements y sont associés, classés du plus grand au plus petit nombre ?", "sql": "SELECT count(*), T1.city FROM organizer AS T1 JOIN conference_event AS T2 ON T1.organizer_id = T2.organizer_id GROUP BY T1.city ORDER BY count(*) DESC"}, {"id": "v2:new:synthetic_046:1:10", "question": "Quels sont les différents pays représentés par les participants, par ordre alphabétique ?", "sql": "SELECT DISTINCT country FROM attendee ORDER BY country"}, {"id": "v2:new:synthetic_046:1:11", "question": "Quels sont les titres et les catégories des événements organisés dans le secteur de la technologie ?", "sql": "SELECT T1.event_title, T1.event_category FROM conference_event AS T1 JOIN organizer AS T2 ON T1.organizer_id = T2.organizer_id WHERE T2.sector = 'technologie'"}, {"id": "v2:new:synthetic_046:1:12", "question": "Quel est le nombre total de participants attendus pour les événements technologiques ayant reçu au moins une inscription ?", "sql": "SELECT sum(T1.expected_attendance) FROM conference_event AS T1 JOIN event_registration AS T2 ON T1.event_id = T2.event_id JOIN organizer AS T3 ON T1.organizer_id = T3.organizer_id WHERE T3.sector = 'technologie'"}, {"id": "v2:new:synthetic_046:1:13", "question": "Affichez les 3 premiers types de salles, triés par capacité moyenne décroissante.", "sql": "SELECT room_type FROM venue_room GROUP BY room_type ORDER BY avg(capacity) DESC LIMIT 3"}, {"id": "v2:new:synthetic_046:1:14", "question": "Affichez le titre de tous les événements dont le nombre de participants attendus est supérieur à 600.", "sql": "SELECT event_title FROM conference_event WHERE expected_attendance > 600"}, {"id": "v2:new:synthetic_046:1:15", "question": "Quels sont les titres des événements dont le nombre de participants attendus est supérieur à 600 ou inférieur à 500 ?", "sql": "SELECT event_title FROM conference_event WHERE expected_attendance > 600 OR expected_attendance < 500"}]}
